1	import {once} from 'node:events';
2	import type {AddressInfo} from 'node:net';
3	import {WebSocket} from 'ws';
4	import type {Express} from 'express';
5	import {createServer} from './createServer.js';
6	import type {HalServer} from './createServer.js';
7	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
8	import {validateMessage} from './ws/validation.js';
9	import {answeringOrchestrator, deferred} from './wsTestSupport.js';
10	import type {SessionResumeOptions} from './ws/sessionResume.js';
11	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
12	import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
13	import type {MessageChunk} from '../types/ai.js';
14	import type {SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
15	import {setLogger} from '../shared/logger.js';
16	
17	// HALEngine#144: a client asks for its own conversation list over the socket it is already authenticated on.
18	// Real upgrades over a real socket, as for resume: what a client is sent is the contract, and no double can observe it.
19	
20	interface WireFrame {
21	  type: string;
22	  sessionId?: string;
23	  resumed?: boolean;
24	  entryCount?: number;
25	  code?: string;
26	  message?: string;
27	  timestamp?: number;
28	  conversations?: unknown;
29	  entry?: unknown;
30	}
31	
32	interface Row {
33	  sessionId: string;
34	  createdAt: unknown;
35	  updatedAt: unknown;
36	  entryCount: number;
37	}
38	
39	const USER = 'u1';
40	const OTHER = 'u2';
41	const UNSUPPORTED = 'UNSUPPORTED';
42	
43	const sleep = (ms: number): Promise<void> => new Promise(resolve => setTimeout(resolve, ms));
44	
45	// Bounded waits, so an absent frame names itself instead of hanging the run out to the suite's timeout.
46	const eventually = async (check: () => boolean): Promise<boolean> => {
47	  for (let attempt = 0; attempt < 300 && !check(); attempt++) await sleep(5);
48	  return check();
49	};
50	
51	const servers: HalServer[] = [];
52	const clients: WebSocket[] = [];
53	const logged: Array<{level: string; category: string; message: string; data?: Record<string, unknown>}> = [];
54	
55	const loggedLines = (): string[] => logged.map(line => JSON.stringify({...line}));
56	
57	// warn and error are recorded; info and debug are silenced, for these tests read frames, not connection chatter.
58	beforeAll(() => {
59	  setLogger({
60	    debug: () => undefined,
61	    info: () => undefined,
62	    warn: (category, message, fields) => void logged.push({level: 'warn', category, message, data: fields}),
63	    error: (category, message, fields) => void logged.push({level: 'error', category, message, data: fields}),
64	  });
65	});
66	
67	afterAll(() => setLogger());
68	
69	beforeEach(() => {
70	  logged.length = 0;
71	});
72	
73	afterEach(async () => {
74	  for (const client of clients.splice(0)) client.terminate();
75	  for (const hal of servers.splice(0)) {
76	    const {wss} = hal;
77	    await eventually(() => wss.clients.size === 0);
78	    await hal.stop();
79	  }
80	});
81	
82	interface EngineOptions {
83	  sessionStore: SessionStore;
84	  history?: {enabled: boolean};
85	  resume?: SessionResumeOptions;
86	  orchestrator?: ChatOrchestrator;
87	}
88	
89	const startEngine = async (options: EngineOptions): Promise<string> => {
90	  // Held in a variable, not a call-site literal, so the new `history` field rides through before the option type has it.
91	  const halOptions = {
92	    app: (() => undefined) as unknown as Express,
93	    wsAuth: async () => ({id: USER}),
94	    sessionStore: options.sessionStore,
95	    orchestrator: options.orchestrator ?? answeringOrchestrator,
96	    resume: options.resume,
97	    history: options.history,
98	  };
99	  const hal = createServer(halOptions);
100	  await hal.start(0);
101	  servers.push(hal);
102	  const {port} = hal.server.address() as AddressInfo;
103	  return `ws://127.0.0.1:${port}/hal/ws`;
104	};
105	
106	const isoAt = (msFromNow: number): string => new Date(Date.now() + msFromNow).toISOString();
107	
108	// A conversation in the store, one entry deep, its activity stamped in the future so the order ignores the clock.
109	const plant = (
110	  store: InMemorySessionStore,
111	  sessionId: string,
112	  userId: string,
113	  activityIso: string,
114	  content: string
115	): void => {
116	  const session = store.create(sessionId, userId);
117	  session.entries.push({role: 'user', content, timestamp: activityIso});
118	};
119	
120	const recordingList = (): {
121	  store: InMemorySessionStore;
122	  calls: Array<{userId: string | number; options?: SessionListOptions}>;
123	} => {
124	  const inner = new InMemorySessionStore();
125	  const calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
126	  const listed = inner.listFor.bind(inner);
127	  const store = Object.assign(inner, {
128	    listFor: (userId: string | number, options?: SessionListOptions): SessionSummary[] => {
129	      calls.push({userId, options});
130	      return listed(userId, options);
131	    },
132	  });
133	  return {store, calls};
134	};
135	
136	// A store written against the five original members: the interface keeps listFor optional beside it.
137	const storeWithoutList = (): SessionStore => {
138	  const inner = new InMemorySessionStore();
139	  return {
140	    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
141	    get: sessionId => inner.get(sessionId),
142	    delete: sessionId => inner.delete(sessionId),
143	    count: () => inner.count(),
144	    clear: () => inner.clear(),
145	  };
146	};
147	
148	const storeWhoseList = (listFor: () => Promise<SessionSummary[]>): InMemorySessionStore =>
149	  Object.assign(new InMemorySessionStore(), {listFor});
150	
151	const listen = (client: WebSocket): WireFrame[] => {
152	  const seen: WireFrame[] = [];
153	  client.on('message', raw => seen.push(JSON.parse(String(raw)) as WireFrame));
154	  return seen;
155	};
156	
157	const frameOf = (seen: WireFrame[], type: string): WireFrame | undefined => seen.find(frame => frame.type === type);
158	
159	const awaitFrame = async (seen: WireFrame[], type: string): Promise<WireFrame> => {
160	  if (!(await eventually(() => frameOf(seen, type) !== undefined))) {
161	    throw new Error(
162	      `no ${type} frame arrived; the frames seen were: ${seen.map(frame => frame.type).join(', ') || 'none'}`
163	    );
164	  }
165	  return frameOf(seen, type) as WireFrame;
166	};
167	
168	const connect = async (url: string): Promise<{client: WebSocket; seen: WireFrame[]}> => {
169	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
170	  clients.push(client);
171	  const seen = listen(client);
172	  await once(client, 'open');
173	  await awaitFrame(seen, 'connected');
174	  return {client, seen};
175	};
176	
177	const announcedId = (seen: WireFrame[]): string => frameOf(seen, 'connected')?.sessionId ?? '';
178	
179	describe('the conversation list over the websocket', () => {
180	  describe('a list_conversations frame', () => {
181	    it('answers with the conversations of the user the connection authenticated, newest first, as ISO strings', async () => {
182	      const stamps = {newest: isoAt(9_000), middle: isoAt(6_000), oldest: isoAt(3_000), other: isoAt(60_000)};
183	      const {store, calls} = recordingList();
184	      plant(store, 'c-oldest', USER, stamps.oldest, 'oldest planted');
185	      plant(store, 'c-middle', USER, stamps.middle, 'middle planted');
186	      plant(store, 'c-newest', USER, stamps.newest, 'newest planted');
187	      plant(store, 'c-other', OTHER, stamps.other, 'another user conversation');
188	
189	      const url = await startEngine({sessionStore: store, history: {enabled: true}});
190	      const {client, seen} = await connect(url);
191	      const own = announcedId(seen);
192	
193	      // The frame names another user; the connection is what decides whose list is answered.
194	      client.send(JSON.stringify({type: 'list_conversations', userId: OTHER}));
195	      const list = await awaitFrame(seen, 'conversation_list');
196	      await sleep(250);
197	
198	      const rows = list.conversations as Row[];
199	      expect(seen.filter(frame => frame.type === 'conversation_list')).toHaveLength(1);
200	      expect(seen.some(frame => frame.type === 'stream_end')).toBe(false);
201	      expect(seen.some(frame => frame.type === 'error')).toBe(false);
202	      expect(rows.map(row => row.sessionId)).toEqual(['c-newest', 'c-middle', 'c-oldest', own]);
203	      expect(rows.map(row => row.entryCount)).toEqual([1, 1, 1, 0]);
204	      for (const row of rows) {
205	        // A summary on the wire is the four fields, its two times ISO strings: a Date does not survive JSON.
206	        expect(Object.keys(row).sort()).toEqual(['createdAt', 'entryCount', 'sessionId', 'updatedAt']);
207	        expect(typeof row.createdAt).toBe('string');
208	        expect(Number.isNaN(Date.parse(String(row.createdAt)))).toBe(false);
209	        expect(typeof row.updatedAt).toBe('string');
210	        expect(Number.isNaN(Date.parse(String(row.updatedAt)))).toBe(false);
211	      }
212	      expect(rows.map(row => String(row.updatedAt))).toEqual([
213	        stamps.newest,
214	        stamps.middle,
215	        stamps.oldest,
216	        expect.any(String),
217	      ]);
218	      // Recorded on the store call, not read off the frames: the user id came from the connection, never the frame.
219	      expect(calls).toHaveLength(1);
220	      expect(calls[0].userId).toBe(USER);
221	    });
222	
223	    it('passes the frame paging options to listFor as the frame sent them, undefined included', async () => {
224	      const {store, calls} = recordingList();
225	      const url = await startEngine({sessionStore: store, history: {enabled: true}});
226	      const {client, seen} = await connect(url);
227	      const own = announcedId(seen);
228	
229	      client.send(JSON.stringify({type: 'list_conversations'}));
230	      const first = await awaitFrame(seen, 'conversation_list');
231	      const rows = first.conversations as Row[];
232	      expect(rows).toHaveLength(1);
233	      expect(rows.at(-1)?.sessionId).toBe(own);
234	
235	      // The cursor a client holds is a row the list itself handed over, its times ISO strings from the wire.
236	      const cursor = {updatedAt: String(rows.at(-1)?.updatedAt), sessionId: own};
237	      client.send(JSON.stringify({type: 'list_conversations', limit: 2, before: cursor}));
238	      await eventually(() => seen.filter(frame => frame.type === 'conversation_list').length === 2);
239	
240	      expect(calls).toHaveLength(2);
241	      expect(calls.map(call => call.userId)).toEqual([USER, USER]);
242	      // Both keys, possibly undefined, rather than the argument omitted: the same call either way.
243	      expect(calls[0].options).toStrictEqual({limit: undefined, before: undefined});
244	      expect(calls[1].options).toStrictEqual({limit: 2, before: cursor});
245	    });
246	  });
247	
248	  describe('the frame shape', () => {
249	    it('accepts a bare list_conversations and forwards no user id, whether history is on or not', () => {
250	      // Validation is static and has no config to ask: the handler, not the validator, refuses it with history off.
251	      expect(validateMessage({type: 'list_conversations'})).toEqual({valid: true, data: {type: 'list_conversations'}});
252	      expect(validateMessage({type: 'list_conversations', userId: OTHER})).toEqual({
253	        valid: true,
254	        data: {type: 'list_conversations'},
255	      });
256	    });
257	
258	    it.each<[string, unknown, string]>([
259	      ['a limit of 0', {type: 'list_conversations', limit: 0}, 'limit'],
260	      ['a limit of 201', {type: 'list_conversations', limit: 201}, 'limit'],
261	      ['a fractional limit', {type: 'list_conversations', limit: 1.5}, 'limit'],
262	      ['a limit sent as a string', {type: 'list_conversations', limit: '10'}, 'limit'],
263	      ['a before that is a bare timestamp', {type: 'list_conversations', before: 'not a date'}, 'before'],
264	      ['a before without its sessionId half', {type: 'list_conversations', before: {updatedAt: isoAt(0)}}, 'before'],
265	      ['a before without its updatedAt half', {type: 'list_conversations', before: {sessionId: 'c1'}}, 'before'],
266	      [
267	        'a before with an unusable moment',
268	        {type: 'list_conversations', before: {updatedAt: 'not a date', sessionId: 'c1'}},
269	        'before',
270	      ],
271	    ])('rejects %s, naming the field', (_label, frame, field) => {
272	      const result = validateMessage(frame);
273	      expect(result.valid).toBe(false);
274	      if (!result.valid) expect(result.error).toContain(field);
275	    });
276	
277	    it('accepts the limit bounds and a whole before cursor', () => {
278	      expect(validateMessage({type: 'list_conversations', limit: 1}).valid).toBe(true);
279	      expect(
280	        validateMessage({type: 'list_conversations', limit: 200, before: {updatedAt: isoAt(0), sessionId: 'c1'}}).valid
281	      ).toBe(true);
282	    });
283	  });
284	
285	  describe('when the frame cannot be answered', () => {
286	    it('answers UNSUPPORTED and no list when history is off or the store cannot list, and warns when history is on without resume', async () => {
287	      // The flag absent is a deployment decision, not an omission to fill with an empty list.
288	      const offUrl = await startEngine({sessionStore: new InMemorySessionStore()});
289	      const off = await connect(offUrl);
290	      off.client.send(JSON.stringify({type: 'list_conversations'}));
291	      const offError = await awaitFrame(off.seen, 'error');
292	
293	      // A store written before lists existed is a misconfiguration to report, not a user with no conversations.
294	      const bareUrl = await startEngine({sessionStore: storeWithoutList(), history: {enabled: true}});
295	      const bare = await connect(bareUrl);
296	      bare.client.send(JSON.stringify({type: 'list_conversations'}));
297	      const bareError = await awaitFrame(bare.seen, 'error');
298	      await sleep(250);
299	
300	      for (const {client, seen} of [off, bare]) {
301	        expect(seen.filter(frame => frame.type === 'conversation_list')).toHaveLength(0);
302	        expect(seen.map(frame => frame.type)).toEqual(['connected', 'error']);
303	        expect(client.readyState).toBe(WebSocket.OPEN);
304	      }
305	      expect(offError.code).toBe(UNSUPPORTED);
306	      expect(bareError.code).toBe(UNSUPPORTED);
307	
308	      // history without resume lists rows no client can open: a deployment slip the engine names at startup.
309	      expect(logged.some(line => line.level === 'warn' && line.message.includes('history'))).toBe(true);
310	    });
311	
312	    it('answers a rejecting store with SERVER_ERROR, the socket open and no store detail anywhere, and one that cannot list with UNSUPPORTED', async () => {
313	      const detail = 'replica set unreachable on mongodb://cluster-a.internal:27017';
314	      const content = 'holiday photos in Kyoto';
315	      const store = storeWhoseList(async () => {
316	        throw new Error(`list failed: ${detail}`);
317	      });
318	      plant(store, 'c-private', USER, isoAt(5_000), content);
319	
320	      const url = await startEngine({sessionStore: store, history: {enabled: true}});
321	      const {client, seen} = await connect(url);
322	      const own = announcedId(seen);
323	
324	      client.send(JSON.stringify({type: 'list_conversations'}));
325	      const failure = await awaitFrame(seen, 'error');
326	      client.send(JSON.stringify({type: 'ping', timestamp: 4321}));
327	      const pong = await awaitFrame(seen, 'pong');
328	      await sleep(250);
329	
330	      expect(seen.filter(frame => frame.type === 'error')).toHaveLength(1);
331	      expect(failure.code).toBe('SERVER_ERROR');
332	      expect(String(failure.message)).not.toContain(detail);
333	      expect(pong.timestamp).toBe(4321);
334	      expect(client.readyState).toBe(WebSocket.OPEN);
335	
336	      const lines = loggedLines();
337	      expect(lines.some(line => line.includes(own))).toBe(true);
338	      expect(lines.some(line => line.includes('cluster-a') || line.includes('replica set'))).toBe(false);
339	      expect(lines.some(line => line.includes(content))).toBe(false);
340	
341	      // The permanent misconfiguration reads as one (issue amendment 3), not as a database that failed.
342	      const {StoreCannotList} = (await import('../types/session.js')) as unknown as {
343	        StoreCannotList?: new (message: string) => Error;
344	      };
345	      if (StoreCannotList === undefined) {
346	        throw new Error('types/session.js exports no StoreCannotList for a store that cannot list to throw');
347	      }
348	      const unable = storeWhoseList(async () => {
349	        throw new StoreCannotList('the collection implements no find');
350	      });
351	      const unableUrl = await startEngine({sessionStore: unable, history: {enabled: true}});
352	      const other = await connect(unableUrl);
353	      other.client.send(JSON.stringify({type: 'list_conversations'}));
354	      const refused = await awaitFrame(other.seen, 'error');
355	      await sleep(250);
356	
357	      expect(other.seen.filter(frame => frame.type === 'conversation_list')).toHaveLength(0);
358	      expect(other.seen.filter(frame => frame.type === 'error')).toHaveLength(1);
359	      expect(refused.code).toBe(UNSUPPORTED);
360	    });
361	  });
362	
363	  describe('beside a streaming turn', () => {
364	    it('answers a list request while the turn is still streaming, before its stream_end', async () => {
365	      const gate = deferred();
366	      const slowStream: ChatOrchestrator = {
367	        processMessage: async () => '',
368	        async *processMessageStream(): AsyncGenerator<MessageChunk> {
369	          yield {type: 'text', text: 'the first half of an answer'};
370	          await gate.until;
371	          yield {type: 'text', text: ', and its second half'};
372	          yield {type: 'stop', stopReason: 'end_turn'};
373	        },
374	      };
375	      const url = await startEngine({
376	        sessionStore: new InMemorySessionStore(),
377	        history: {enabled: true},
378	        orchestrator: slowStream,
379	      });
380	      const {client, seen} = await connect(url);
381	
382	      client.send(JSON.stringify({type: 'user_message', content: 'a question with a long answer'}));
383	      await awaitFrame(seen, 'entry_delta');
384	
385	      client.send(JSON.stringify({type: 'list_conversations'}));
386	      const list = await awaitFrame(seen, 'conversation_list');
387	
388	      // A history request is not a turn: it must not queue behind the answer in flight.
389	      expect(seen.some(frame => frame.type === 'stream_end')).toBe(false);
390	
391	      gate.release();
392	      await awaitFrame(seen, 'stream_end');
393	      expect(seen.indexOf(list)).toBeLessThan(seen.findIndex(frame => frame.type === 'stream_end'));
394	    });
395	  });
396	
397	  describe('into a conversation', () => {
398	    it('reopens a listed conversation by reconnecting with its id, through the resume path that already ships', async () => {
399	      const url = await startEngine({
400	        sessionStore: new InMemorySessionStore(),
401	        history: {enabled: true},
402	        resume: {enabled: true},
403	      });
404	      const first = await connect(url);
405	      const own = announcedId(first.seen);
406	
407	      first.client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
408	      await awaitFrame(first.seen, 'stream_end');
409	      first.client.send(JSON.stringify({type: 'list_conversations'}));
410	      const list = await awaitFrame(first.seen, 'conversation_list');
411	      const rows = list.conversations as Row[];
412	      const row = rows.find(candidate => candidate.sessionId === own);
413	      if (row === undefined) {
414	        throw new Error(
415	          `the conversation the client is in is not listed; the rows were: ${rows.map(r => r.sessionId).join(', ') || 'none'}`
416	        );
417	      }
418	
419	      first.client.close();
420	      const again = await connect(`${url}?sessionId=${row.sessionId}`);
421	      const connected = frameOf(again.seen, 'connected') as WireFrame;
422	
423	      expect(connected.resumed).toBe(true);
424	      expect(connected.entryCount).toBe(2);
425	      const upserts = again.seen.filter(frame => frame.type === 'entry_upsert');
426	      expect(upserts.map(frame => frame.entry)).toMatchObject([
427	        {role: 'user', content: 'hello'},
428	        {role: 'assistant', content: 'hi', isStreaming: false},
429	      ]);
430	    });
431	  });
432	});
